/// `Err(message)` naming [`INSTALL_DOC_PATH`] iff `current` (the committed
/// file's content) differs from a fresh render over `base`.
pub fn check_install_doc(current: &str, base: &str) -> Result<(), String> {
    if current == crate::install_links::render_install_doc(base) {
        Ok(())
    } else {
        Err(format!("gen-docs --check: {INSTALL_DOC_PATH} is stale (run `mcphost gen-docs`)"))
    }
}

/// One `billing::plans_from_catalog`-shaped row, rendered as a markdown
/// table row -- requirement 3's own fields (name, price, tools, calls/day,
/// secrets), plus a short prose description already on the `Plan` struct.
fn render_plan_row(p: &Plan) -> String {
    format!(
        "| {name} | ${price}/mo | {tools} | {calls} | {secrets} | {description} |",
        name = p.name,
        price = p.price_usd_month,
        tools = p.tools_max,
        calls = p.calls_per_day,
        secrets = p.secrets_max,
        description = p.description,
    )
}

/// The one function both [`run`] (writes/`--check`s the committed file) and
/// `tests/support_ac04_*` (the hermetic "byte-identical to a fresh render"
/// AC4 test) call -- the single source `docs/plans.md`'s own committed text
/// must always equal.
pub fn render_plans_markdown(catalog: &PlanCatalog) -> String {
    let mut out = String::new();
    out.push_str("# Plans\n\n");
    out.push_str(
        "Generated by `mcphost gen-docs` from the same `PlanCatalog` the \
         `billing.plans` tool and `/plans.json` read -- these numbers can't \
         drift from what the server actually enforces. Do not hand-edit; \
         run `mcphost gen-docs` after changing `plans.toml` (or its \
         built-in defaults) instead.\n\n",
    );
    out.push_str("| plan | price | tools | calls/day | secrets | description |\n");
    out.push_str("|---|---|---|---|---|---|\n");
    for plan in &catalog.plans {
        out.push_str(&render_plan_row(plan));
        out.push('\n');
    }
    out.push_str(
        "\nStorage, table, job-concurrency, and every other per-plan quota \
         (state/table/docs byte caps, `jobs_concurrent`, `channels_max`, \
         ...) are visible on a signed-up tenant's own `host.whoami` and \
         `host.usage`, and in `admin.usage` for an operator -- this page \
         covers the five numbers a developer decides on *before* signing \
         up, the ones `billing.plans` itself returns.\n",
    );
    out.push_str("\nMachine-readable: [`/plans.json`](/plans.json).\n");
    out.push_str(&render_ceilings_table(catalog));
    out.push_str(&render_pricing_table(catalog));
    out
}

/// PRD-mcphost-pricing-page-from-plan-table R5: the price fields of the
/// plan table (`NON_CEILING_FIELDS`, so absent from the ceilings table
/// above), one row per field and one column per plan.
pub fn render_pricing_table(catalog: &PlanCatalog) -> String {
    let mut out = String::from("\n## Plan pricing\n\n");
    out.push_str(
        "Price and included volume, as `/plans.json` and `billing.plans` \
         report them. `overage_usd_per_1000_calls` is whole USD per 1000 \
         calls past `calls_included_month`.\n\n",
    );
    out.push_str("| field |");
    for plan in &catalog.plans {
        out.push_str(&format!(" {} |", plan.name));
    }
    out.push_str("\n|---|");
    for _ in &catalog.plans {
        out.push_str("---|");
    }
    out.push('\n');
    type Field = (&'static str, fn(&Plan) -> i64);
    let fields: [Field; 3] = [
        ("price_usd_month", |p| p.price_usd_month),
        ("calls_included_month", |p| p.calls_included_month),
        ("overage_usd_per_1000_calls", |p| p.overage_usd_per_1000_calls),
    ];
    for (name, get) in fields {
        out.push_str(&format!("| `{name}` |"));
        for plan in &catalog.plans {
            out.push_str(&format!(" {} |", get(plan)));
        }
        out.push('\n');
    }
    out
}

/// PRD-mcphost-plan-limits-generated: one row per numeric plan ceiling, one
/// column per plan, derived from [`crate::plans::Plan::ceilings_flat`] -- the
/// same function `host.quickstart`'s `limits.plan` is built from.
pub fn render_ceilings_table(catalog: &PlanCatalog) -> String {
    let mut out = String::from("\n## Plan ceilings\n\n");
    out.push_str(
        "Every numeric ceiling in the plan table, as `host.quickstart` \
         `limits.plan` reports it for your plan. A `budget` value above \
         your plan's row is refused with `budget_ceiling_exceeded`.\n\n",
    );
    out.push_str("| ceiling |");
    for plan in &catalog.plans {
        out.push_str(&format!(" {} |", plan.name));
    }
    out.push_str("\n|---|");
    for _ in &catalog.plans {
        out.push_str("---|");
    }
    out.push('\n');
    let columns: Vec<Vec<(String, i64)>> = catalog.plans.iter().map(|p| p.ceilings_flat()).collect();
    if let Some(first) = columns.first() {
        for (i, (name, _)) in first.iter().enumerate() {
            out.push_str(&format!("| `{name}` |"));
            for col in &columns {
                match col.get(i) {
                    Some((n, v)) if n == name => out.push_str(&format!(" {v} |")),
                    _ => out.push_str(" - |"),
                }
            }
            out.push('\n');
        }
    }
    out
}

/// AC4's other generated file: `www/plans.html`'s committed text must
